Lemma cmap_alt_agree : forall (live : list (Z * Z)) (P : Z -> Prop) (m m' : mem) pcm cv (X : Prop),
  (pcm = 0 \/ (cmap_obj live m pcm cv /\ X)) -> agree_on P m m' ->
